package ru.wsn.capture.core

import org.json.JSONObject
import kotlin.math.exp
import kotlin.math.ln
import kotlin.math.max

/** The flat's room model on the phone: the inference half of server/wsn/zonemodel.py (link features, per-link
 *  standardisation, a small MLP ensemble -> P(zone) over rooms+empty and P(moving)). Loaded from model.json
 *  (the server's JSON sidecar of the trained model). Float-for-float parity with Python is checked by golden
 *  vectors generated by the Python code itself. */
object ZoneFeatures {
    const val NF = 6          // log_e_rel, log_e_last_rel, log_jit_rel, log_dev_rel, log_e, alive
    const val STATS = 4       // e, e_last, jit, dev
    const val EPS = 1e-4

    /** Features of one link in one window; a silent link (st == null) is all zeros with alive = 0. */
    fun linkFeatures(st: DoubleArray?, level: DoubleArray?): DoubleArray {
        val out = DoubleArray(NF)
        if (st == null) return out
        if (level != null) for (i in 0 until 4) out[i] = ln((st[i] + EPS) / (level[i] + EPS))
        out[4] = ln(st[0] + EPS)
        out[5] = 1.0
        return out
    }
}

class ZoneModel private constructor(
    val version: Int,
    val links: List<String>,
    val zones: List<String>,      // last is EMPTY
    private val mu: Array<DoubleArray>,
    private val sd: Array<DoubleArray>,
    private val nets: List<Net>,
    /** Fingerprints of the walk: the first net's last hidden layer of each labelled window and where the phone
     *  (the person) was then. A live window is placed by its nearest fingerprints (kNN). Absent in old models. */
    private val fpE: Array<DoubleArray> = emptyArray(),
    private val fpP: Array<DoubleArray> = emptyArray(),
    /** Median error of that placement, metres, checked on the walk without the 30 s around each window. */
    val fpErr: Double = Double.NaN,
    /** 75th percentile of that error: the halo around the dot ("usually within"). */
    val fpErr75: Double = Double.NaN,
    private val fpK: Int = 7,
) {
    private class Net(
        val w1: Array<DoubleArray>, val b1: DoubleArray, val w2: Array<DoubleArray>, val b2: DoubleArray,
        val wz: Array<DoubleArray>, val bz: DoubleArray, val wm: Array<DoubleArray>, val bm: DoubleArray,
    )

    private val nf = ZoneFeatures.NF
    private val l = links.size

    /** One window's standardised net input: per link, live features (x-mu)/sd else 0, then the alive flag. */
    private fun standardizeRow(x: Array<DoubleArray>): DoubleArray {
        val z = DoubleArray(l * nf)
        for (j in 0 until l) {
            val alive = x[j][nf - 1] > 0.5
            for (f in 0 until nf - 1) z[j * nf + f] = if (alive) (x[j][f] - mu[j][f]) / sd[j][f] else 0.0
            z[j * nf + (nf - 1)] = if (alive) 1.0 else 0.0
        }
        return z
    }

    private fun relu(v: DoubleArray) = DoubleArray(v.size) { if (v[it] > 0.0) v[it] else 0.0 }

    private fun matvec(w: Array<DoubleArray>, x: DoubleArray, b: DoubleArray): DoubleArray {
        // w has shape [in, out]; returns x·w + b, length out
        val out = b.copyOf()
        for (i in x.indices) {
            val xi = x[i]; if (xi == 0.0) continue
            val row = w[i]
            for (o in out.indices) out[o] += xi * row[o]
        }
        return out
    }

    private fun softmax(x: DoubleArray): DoubleArray {
        var m = x[0]; for (v in x) if (v > m) m = v
        var s = 0.0; val e = DoubleArray(x.size) { exp(x[it] - m).also { v -> s += v } }
        for (i in e.indices) e[i] /= s
        return e
    }

    private fun sigmoid(x: Double) = 1.0 / (1.0 + exp(-x.coerceIn(-30.0, 30.0)))

    /** X[n][link][NF] (feature vectors from linkFeatures) -> P(zone)[n][zones], P(moving)[n], mean over nets. */
    fun predict(x: Array<Array<DoubleArray>>): Pair<Array<DoubleArray>, DoubleArray> {
        val pz = Array(x.size) { DoubleArray(zones.size) }
        val pm = DoubleArray(x.size)
        for (n in x.indices) {
            val z = standardizeRow(x[n])
            for (net in nets) {
                val h1 = relu(matvec(net.w1, z, net.b1))
                val h2 = relu(matvec(net.w2, h1, net.b2))
                val lz = matvec(net.wz, h2, net.bz)
                val lm = matvec(net.wm, h2, net.bm)[0]
                val sm = softmax(lz)
                for (k in pz[n].indices) pz[n][k] += sm[k]
                pm[n] += sigmoid(lm)
            }
            for (k in pz[n].indices) pz[n][k] /= nets.size
            pm[n] /= nets.size
        }
        return pz to pm
    }

    /** The first net's last hidden layer for each window: the space the fingerprints live in. */
    fun embed(x: Array<Array<DoubleArray>>): Array<DoubleArray> {
        val net = nets[0]
        return Array(x.size) { n -> relu(matvec(net.w2, relu(matvec(net.w1, standardizeRow(x[n]), net.b1)), net.b2)) }
    }

    val canLocate: Boolean get() = fpE.isNotEmpty()

    /** Where the person probably is: weighted mean of the K nearest fingerprints, and their spread (metres). */
    data class Fix(val x: Double, val y: Double, val spread: Double)

    fun locate(x: Array<Array<DoubleArray>>, k: Int = fpK): Fix? {
        if (fpE.isEmpty()) return null
        return nearest(embed(x)[0], fpE, fpP, k, skip = null)
    }

    /** Room with the highest probability given somebody is home, its probability, and the empty probability. */
    data class Verdict(val zone: String, val zoneP: Double, val emptyP: Double, val movingP: Double,
                       val probs: Map<String, Double>, val linksLive: Int)

    fun verdict(x: Array<Array<DoubleArray>>): Verdict {
        val (pz, pm) = predict(x)
        val p = pz[0]
        val rooms = zones.subList(0, zones.size - 1)
        var sum = 0.0; for (i in rooms.indices) sum += p[i]
        sum = max(sum, 1e-9)
        val pr = DoubleArray(rooms.size) { p[it] / sum }
        var best = 0; for (i in pr.indices) if (pr[i] > pr[best]) best = i
        val live = (0 until l).count { x[0][it][ZoneFeatures.NF - 1] > 0.5 }
        return Verdict(rooms[best], pr[best], p[p.size - 1], pm[0],
            rooms.indices.associate { rooms[it] to pr[it] }, live)
    }

    companion object {
        private fun mat(o: org.json.JSONArray): Array<DoubleArray> =
            Array(o.length()) { i -> o.getJSONArray(i).let { r -> DoubleArray(r.length()) { r.getDouble(it) } } }
        private fun vec(o: org.json.JSONArray) = DoubleArray(o.length()) { o.getDouble(it) }

        /** kNN in embedding space; skip(i) excludes candidates (the honest check leaves out time neighbours). */
        fun nearest(e: DoubleArray, fpE: Array<DoubleArray>, fpP: Array<DoubleArray>, k: Int, skip: ((Int) -> Boolean)?): Fix? {
            val d = ArrayList<Pair<Double, Int>>(fpE.size)
            for (i in fpE.indices) {
                if (skip != null && skip(i)) continue
                var s = 0.0; val f = fpE[i]
                for (j in e.indices) { val q = e[j] - f[j]; s += q * q }
                d.add(s to i)
            }
            if (d.isEmpty()) return null
            d.sortBy { it.first }
            val top = d.take(k)
            var w = 0.0; var x = 0.0; var y = 0.0
            for ((s, i) in top) { val wi = 1.0 / (kotlin.math.sqrt(s) + 1e-3); w += wi; x += wi * fpP[i][0]; y += wi * fpP[i][1] }
            x /= w; y /= w
            var v = 0.0
            for ((s, i) in top) { val wi = 1.0 / (kotlin.math.sqrt(s) + 1e-3); v += wi * ((fpP[i][0] - x) * (fpP[i][0] - x) + (fpP[i][1] - y) * (fpP[i][1] - y)) }
            return Fix(x, y, kotlin.math.sqrt(v / w))
        }

        fun fromJson(text: String): ZoneModel {
            val j = JSONObject(text)
            val links = j.getJSONArray("links").let { a -> List(a.length()) { a.getString(it) } }
            val zones = j.getJSONArray("zones").let { a -> List(a.length()) { a.getString(it) } }
            val nets = j.getJSONArray("nets").let { arr ->
                List(arr.length()) { i ->
                    val n = arr.getJSONObject(i)
                    Net(mat(n.getJSONArray("W1")), vec(n.getJSONArray("b1")), mat(n.getJSONArray("W2")),
                        vec(n.getJSONArray("b2")), mat(n.getJSONArray("Wz")), vec(n.getJSONArray("bz")),
                        mat(n.getJSONArray("Wm")), vec(n.getJSONArray("bm")))
                }
            }
            val fp = j.optJSONObject("fp")
            return ZoneModel(j.optInt("version", 0), links, zones,
                mat(j.getJSONArray("mu")), mat(j.getJSONArray("sd")), nets,
                fp?.optJSONArray("e")?.let { mat(it) } ?: emptyArray(),
                fp?.optJSONArray("p")?.let { mat(it) } ?: emptyArray(),
                fp?.optDouble("err", Double.NaN) ?: Double.NaN,
                fp?.optDouble("err75", Double.NaN) ?: Double.NaN,
                fp?.optInt("k", 7) ?: 7)
        }
    }
}
